function validate([operations, args]) {
  if (operations[0] !== 'ValidWordAbbr' || args[0].length !== 1) return 'Start with ValidWordAbbr and its dictionary.';
  const dictionary = args[0][0];
  if (dictionary.length < 1 || dictionary.length > 30000) return 'dictionary needs 1 to 3 * 10^4 words.';
  if (dictionary.some(w => !/^[a-z]{1,20}$/.test(w))) return 'Each dictionary word has 1 to 20 lowercase letters.';
  if (operations.length - 1 > 5000) return 'At most 5000 calls to isUnique.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'isUnique') return 'Only isUnique can follow the constructor.';
    if (!/^[a-z]{1,20}$/.test(args[i][0])) return 'Each query word has 1 to 20 lowercase letters.';
  }
  return null;
}

