class ValidWordAbbr {
  constructor(dictionary) {
    this.owner = new Map();
    for (const word of dictionary) {
      const abbr = this.abbreviate(word);
      if (!this.owner.has(abbr)) {
        this.owner.set(abbr, word);
      } else if (this.owner.get(abbr) !== word) {
        this.owner.set(abbr, null);
      }
    }
  }

  abbreviate(word) {
    if (word.length <= 2) {
      return word;
    }
    return word[0] + (word.length - 2) + word[word.length - 1];
  }

  isUnique(word) {
    const abbr = this.abbreviate(word);
    if (!this.owner.has(abbr)) {
      return true;
    }
    return this.owner.get(abbr) === word;
  }
}

