class ValidWordAbbr {
  constructor(dictionary) {
    this.words = dictionary.slice();
  }
  isUnique(word) {
    // Two words share an abbreviation exactly when they have the same length,
    // the same first letter and the same last letter (short words then are equal).
    for (const other of this.words) {
      if (other === word) continue;
      if (other.length === word.length && other[0] === word[0] && other[other.length - 1] === word[word.length - 1]) return false;
    }
    return true;
  }
}

