function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  // A tiny alphabet and short words make shared abbreviations common.
  const letters = large ? 'abcdef' : rand() < 0.5 ? 'ab' : 'abcz';
  const longest = large ? 20 : 1 + pick(5);
  const makeWord = () => Array.from({ length: 1 + pick(longest) }, () => letters[pick(letters.length)]).join('');
  const dictionary = [];
  const count = large ? 2000 : 1 + pick(6);
  while (dictionary.length < count) {
    dictionary.push(dictionary.length && rand() < 0.2 ? dictionary[pick(dictionary.length)] : makeWord());
  }
  const operations = ['ValidWordAbbr'];
  const args = [[dictionary]];
  const calls = large ? 499 : 1 + pick(6);
  for (let c = 0; c < calls; c++) {
    operations.push('isUnique');
    args.push([rand() < 0.4 ? dictionary[pick(dictionary.length)] : makeWord()]);
  }
  return [operations, args];
}
